  if exists (select 1 from public.sent_messages where workspace_id is null) then
    perform set_config('session_replication_role', 'replica', true);
    update public.sent_messages set workspace_id = 'f5a1e000-0000-4000-8000-000000000001'::uuid
     where ctid = any (array(select ctid from public.sent_messages where workspace_id is null limit 1000));
    get diagnostics n = row_count;
    perform set_config('session_replication_role', 'origin', true);
    raise notice '0034: backfilled % row(s) in sent_messages', n;
  end if;
end $$;
commit;
